void _ui_object_deleted(lv_event_t * e)
{
    /* 引用随对象自身删除失效，不依赖屏幕析构入口。 */
    lv_obj_t ** reference = (lv_obj_t **)lv_event_get_user_data(e);
    if (reference != NULL && *reference == lv_event_get_target(e)) *reference = NULL;
}

void _ui_basic_set_property(lv_obj_t * target, int id, int val)
{
    if(target == NULL) return;
    if(id == _UI_BASIC_PROPERTY_POSITION_X) lv_obj_set_x(target, val);
    else if(id == _UI_BASIC_PROPERTY_POSITION_Y) lv_obj_set_y(target, val);
    else if(id == _UI_BASIC_PROPERTY_WIDTH) lv_obj_set_width(target, val);
    else if(id == _UI_BASIC_PROPERTY_HEIGHT) lv_obj_set_height(target, val);
}

