static void _ui_format_value(char * buf, size_t size, int32_t value, const char * prefix, const char * postfix)
{
    lv_snprintf(buf, size, "%s%d%s", prefix ? prefix : "", (int)value, postfix ? postfix : "");
}

void _ui_screen_change(lv_obj_t ** target, int fademode, uint32_t speed, uint32_t delay)
{
    if(target == NULL || *target == NULL) return;
#if LVGL_VERSION_MAJOR >= 9
    lv_screen_load_anim(*target, (lv_screen_load_anim_t)fademode, speed, delay, false);
#else
    lv_scr_load_anim(*target, (lv_scr_load_anim_t)fademode, speed, delay, false);
#endif
}

void _ui_flag_modify(lv_obj_t * target, lv_obj_flag_t flag, ui_modify_flag_t action)
{
    if(target == NULL) return;
    if(action == _UI_MODIFY_FLAG_ADD) lv_obj_add_flag(target, flag);
    else if(action == _UI_MODIFY_FLAG_REMOVE) lv_obj_clear_flag(target, flag);
    else {
        if(lv_obj_has_flag(target, flag)) lv_obj_clear_flag(target, flag);
        else lv_obj_add_flag(target, flag);
    }
}

void _ui_state_modify(lv_obj_t * target, lv_state_t state, ui_modify_state_t action)
{
    if(target == NULL) return;
    if(action == _UI_MODIFY_STATE_ADD) lv_obj_add_state(target, state);
    else if(action == _UI_MODIFY_STATE_REMOVE) lv_obj_clear_state(target, state);
    else {
        if(lv_obj_has_state(target, state)) lv_obj_clear_state(target, state);
        else lv_obj_add_state(target, state);
    }
}

